(function(){var list=document.querySelector('[data-sortable-lessons]');if(!list)return;var dragged=null;list.querySelectorAll('[data-sort-id]').forEach(function(row){row.addEventListener('dragstart',function(){dragged=row;row.classList.add('is-dragging')});row.addEventListener('dragend',function(){row.classList.remove('is-dragging');if(dragged){var order=[].slice.call(list.querySelectorAll('[data-sort-id]')).map(function(x){return x.dataset.sortId});fetch(list.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':list.dataset.csrf,'Accept':'application/json'},body:JSON.stringify({order:order})}).then(function(){window.location.reload()});dragged=null}});row.addEventListener('dragover',function(event){event.preventDefault();if(dragged&&dragged!==row){var rect=row.getBoundingClientRect();list.insertBefore(dragged,event.clientY<rect.top+rect.height/2?row:row.nextSibling)}})});})();
